<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $item = DB::table("stock_movements")->select("item_id")->groupBy("item_id")->orderByRaw("COUNT(*) DESC")->first(); $movements = DB::table("stock_movements")->where("item_id", $item->item_id)->get(); foreach($movements as $m) { echo "{$m->moved_at} | {$m->movement_type} | IN: {$m->qty_in} | OUT: {$m->qty_out}\n"; }
